void generateXBM(gdImagePtr image, char* file_name, int fg, gdIOCtx* out) {
    int width = image->sx;
    int height = image->sy;
    int i, j;
    unsigned char* pixelData;
    char* baseName = file_name;

    // Remove .xbm extension if present
    if (strlen(file_name) > 4 && strcmp(file_name + strlen(file_name) - 4, ".xbm") == 0) {
        baseName = file_name;
        baseName[strlen(file_name) - 4] = '\0';
    }

    // Output width and height as preprocessor definitions
    char widthStr[32];
    char heightStr[32];
    sprintf(widthStr, "#define %s_width %d\n", baseName, width);
    sprintf(heightStr, "#define %s_height %d\n", baseName, height);
    gdPutBuf(out, (void*)widthStr, strlen(widthStr));
    gdPutBuf(out, (void*)heightStr, strlen(heightStr));

    // Output the static pixel data array
    char pixelArrayHeader[256];
    sprintf(pixelArrayHeader, "static unsigned char %s_bits[] = {\n    ", baseName);
    gdPutBuf(out, (void*)pixelArrayHeader, strlen(pixelArrayHeader));

    pixelData = (unsigned char*)malloc((width + 7) / 8 * height);
    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            int color = gdImageGetPixel(image, j, i);
            if (color == fg) {
                pixelData[i * ((width + 7) / 8) + (j / 8)] |= (1 << (7 - (j % 8)));
            }
        }
    }

    for (i = 0; i < ((width + 7) / 8) * height; i++) {
        char byteStr[16];
        sprintf(byteStr, "0x%02X", pixelData[i]);
        gdPutBuf(out, (void*)byteStr, strlen(byteStr));
        if (i < ((width + 7) / 8) * height - 1) {
            gdPutBuf(out, (void*)", ", 2);
        }
        if ((i + 1) % 8 == 0) {
            gdPutBuf(out, (void*)"\n    ", 4);
        }
    }

    char pixelArrayFooter[] = "\n};\n";
    gdPutBuf(out, (void*)pixelArrayFooter, strlen(pixelArrayFooter));

    free(pixelData);
}

void gdImageXBM(gdImagePtr image, char* file_name, int fg, gdIOCtx* out)
{
	char* base_name = file_name;
	char* p;
	for (p = base_name; *p; p++) {
		if (!isalnum((unsigned char)*p)) {
			*p = '_';
		}
	}

	int width = image->sx;
	int height = image->sy;

	/* Output width and height as preprocessor definitions */
	gdPutCHAR('#', out);
	gdPutCHAR('d', out);
	gdPutCHAR('e', out);
	gdPutCHAR('f', out);
	gdPutCHAR('i', out);
	gdPutCHAR('n', out);
	gdPutCHAR('e', out);
	gdPutCHAR(' ', out);
	gdPutString(base_name, out);
	gdPutCHAR('_', out);
	gdPutCHAR('W', out);
	gdPutCHAR('I', out);
	gdPutCHAR('D', out);
	gdPutCHAR('T', out);
	gdPutCHAR('H', out);
	gdPutCHAR(' ', out);
	gdPutInt(width, out);
	gdPutCHAR('\n', out);

	gdPutCHAR('#', out);
	gdPutCHAR('d', out);
	gdPutCHAR('e', out);
	gdPutCHAR('f', out);
	gdPutCHAR('i', out);
	gdPutCHAR('n', out);
	gdPutCHAR('e', out);
	gdPutCHAR(' ', out);
	gdPutString(base_name, out);
	gdPutCHAR('_', out);
	gdPutCHAR('H', out);
	gdPutCHAR('E', out);
	gdPutCHAR('I', out);
	gdPutCHAR('G', out);
	gdPutCHAR('H', out);
	gdPutCHAR('T', out);
	gdPutCHAR(' ', out);
	gdPutInt(height, out);
	gdPutCHAR('\n', out);

	/* Output pixel data as a static unsigned char array */
	gdPutCHAR('#', out);
	gdPutCHAR('d', out);
	gdPutCHAR('e', out);
	gdPutCHAR('f', out);
	gdPutCHAR('i', out);
	gdPutCHAR('n', out);
	gdPutCHAR('e', out);
	gdPutCHAR(' ', out);
	gdPutString(base_name, out);
	gdPutCHAR(' ', out);
	gdPutCHAR('{', out);
	gdPutCHAR('\n', out);

	int y, x;
	int bits = 0;
	int bit = 0;
	unsigned char b = 0;
	for (y = 0; y < height; y++) {
		for (x = 0; x < width; x++) {
			int c = gdImageGetPixel(image, x, y);
			if (c == fg) {
				b |= (1 << bit);
			}
			bit++;
			if (bit == 8) {
				gdPutCHAR(' ', out);
				gdPutCHAR('0', out);
				gdPutCHAR('x', out);
				gdPutChar((b >> 4) + '0', out);
				gdPutChar((b & 0xf) + ((b & 0xf) < 10 ? '0' : 'a' - 10), out);
				bits++;
				bit = 0;
				b = 0;
				if ((bits % 16) == 0) {
					gdPutCHAR('\n', out);
				} else {
					gdPutCHAR(' ', out);
				}
			}
		}
	}
	if (bit > 0) {
		gdPutCHAR(' ', out);
		gdPutCHAR('0', out);
		gdPutCHAR('x', out);
		gdPutChar((b >> 4) + '0', out);
		gdPutChar((b & 0xf) + ((b & 0xf) < 10 ? '0' : 'a' - 10), out);
		gdPutCHAR('\n', out);
	}
	gdPutCHAR('}', out);
}

