        fname = "image";
    }

    for (p = fname; *p; p++) {
        c = (unsigned char)*p;
        if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c == '_') || (c >= '0' && c <= '9')) {
            len++;
        }
    }

    outstr = (char*)malloc(len + 1);
    if (!outstr) {
        return;
    }

    for (p = fname, x = 0; *p; p++) {
        c = (unsigned char)*p;
        if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c == '_') || (c >= '0' && c <= '9')) {
            outstr[x++] = *p;
        }
    }
    outstr[x] = 0;

    for (i = 0; i < len; i++) {
        if (outstr[i] == '_') {
            outstr[i] = '0';
