    gdputc('#', out);
    gdputc('d', out);
    gdputc('e', out);
    gdputc('f', out);
    gdputc('i', out);
    gdputc('n', out);
    gdputc('e', out);
    gdputc(' ', out);

    for (i = 0; i < len; i++) {
        gdputc(outstr[i], out);
    }

    gdputc('H', out);
    gdputc('E', out);
    gdputc('I', out);
    gdputc('G', out);
    gdputc('H', out);
    gdputc('T', out);
    gdputc(' ', out);
    gdPutLong(out, height);

    gdputc('\n', out);
    gdputc('s', out);
    gdputc('t', out);
    gdputc('a', out);
    gdputc('t', out);
    gdputc('i', out);
    gdputc('c', out);
    gdputc(' ', out);
    gdputc('u', out);
    gdputc('n', out);
    gdputc('s', out);
    gdputc('i', out);
    gdputc('g', out);
    gdputc('n', out);
    gdputc('e', out);
    gdputc('d', out);
    gdputc(' ', out);
    gdputc('c', out);
    gdputc('h', out);
    gdputc('a', out);
    gdputc('r', out);
    gdputc(' ', out);

    for (i = 0; i < len; i++) {
        gdputc(outstr[i], out);
    }

    gdputc('d', out);
    gdputc('a', out);
    gdputc('t', out);
    gdputc('a', out);
    gdputc('[', out);
    gdPutLong(out, height);
    gdputc(']', out);
    gdputc(' ', out);
    gdputc('=', out);
    gdputc(' ', out);
    gdputc('{', out);
    gdputc('\n', out);

    for (i = 0; i < height; i++) {
        if (i % 8 == 0) {
            if (i > 0) {
                gdputc(' ', out);
                gdPutLong(out, 0);
                gdputc(',', out);
                gdputc('\n', out);
            }
        } else {
            gdputc(' ', out);
        }

        if (i % 8 == 0) {
            gdputc(' ', out);
        }

        for (j = 0; j < width; j++) {
            if (j < width) {
                if (gdImageGetPixel(image, j, i) == fg) {
                    gdputc('1', out);
                } else {
                    gdputc('0', out);
                }
            }
        }

        if (i < height - 1) {
            gdputc(',', out);
            if ((i + 1) % 8 == 0) {
                gdputc('\n', out);
            }
        }
    }

    gdputc('\n', out);
    gdputc('}', out);
    gdputc(';', out);
    gdputc('\n', out);

    free(outstr);
}

void generateXBM(gdImagePtr image, char* file_name, int fg, gdIOCtx* out)
{
    int width = image->sx;
    int height = image->sy;
    int i, j;
    int row;
    int rowBytes = (width + 7) / 8;
    unsigned char* pixelData = (unsigned char*)malloc(rowBytes * height);

    if (!pixelData) {
        return;
    }

    for (row = 0; row < height; row++) {
        unsigned char* rowPtr = &pixelData[row * rowBytes];
        for (j = 0; j < width; j++) {
            int bytePos = j / 8;
            int bitPos = 7 - (j % 8);
            int color = gdImageGetPixel(image, j, row);
            rowPtr[bytePos] |= ((color == fg) ? 1 << bitPos : 0);
        }
    }

    fprintf(out->output_file, "/* X11 bitmap file for %s */\n", file_name);
    fprintf(out->output_file, "#define %s_width %d\n", file_name, width);
    fprintf(out->output_file, "#define %s_height %d\n", file_name, height);
    fprintf(out->output_file, "static unsigned char %s_bits[] = {\n  ", file_name);

    for (i = 0; i < rowBytes * height; i++) {
        if (i % 16 == 0) {
            fprintf(out->output_file, "\n  ");
        }
        fprintf(out->output_file, "0x%02X, ", pixelData[i]);
    }
    fprintf(out->output_file, "\n};\n");

    free(pixelData);
}

void gdImageXBM(gdImagePtr image, char* file_name, int fg, gdIOCtx* out) {
    int width = image->sx;
    int height = image->sy;
    int i, j;
    int c;
    char* base = file_name;
    char* p = base;

    /* Strip directory components from file name */
    while (*p) {
        if (*p == '/') {
            base = p + 1;
        }
        p++;
    }

    /* Replace invalid characters in the base name with underscores */
    for (p = base; *p; p++) {
        if (!isalnum(*p) && *p != '_') {
            *p = '_';
        }
    }

    /* Write the XBM header */
    gdPutChar(out, '#');
    gdPutChar(out, 'd');
    gdPutChar(out, 'e');
    gdPutChar(out, 'f');
    gdPutChar(out, 'i');
    gdPutChar(out, 'n');
    gdPutChar(out, 'e');
    gdPutChar(out, ' ');
    for (i = 0; base[i]; i++) {
        gdPutChar(out, base[i]);
    }
    gdPutChar(out, '_');
    gdPutChar(out, 'w');
    gdPutChar(out, 'i');
    gdPutChar(out, 'd');
    gdPutChar(out, 't');
    gdPutChar(out, 'h');
    gdPutChar(out, ' ');
    for (i = 0; width; i++) {
        int d = width % 10;
        width = width / 10;
        gdPutChar(out, '0' + d);
    }
    for (i = i - 1; i >= 0; i--) {
        gdPutChar(out, '0');
    }
    gdPutChar(out, '\n');

    gdPutChar(out, '#');
    gdPutChar(out, 'd');
    gdPutChar(out, 'e');
    gdPutChar(out, 'f');
    gdPutChar(out, 'i');
    gdPutChar(out, 'n');
    gdPutChar(out, 'e');
    gdPutChar(out, ' ');
    for (i = 0; base[i]; i++) {
        gdPutChar(out, base[i]);
    }
    gdPutChar(out, '_');
    gdPutChar(out, 'h');
    gdPutChar(out, 'e');
    gdPutChar(out, 'i');
    gdPutChar(out, 'g');
    gdPutChar(out, 'h');
    gdPutChar(out, 't');
    gdPutChar(out, ' ');
    for (i = 0; height; i++) {
        int d = height % 10;
        height = height / 10;
        gdPutChar(out, '0' + d);
    }
    for (i = i - 1; i >= 0; i--) {
        gdPutChar(out, '0');
    }
    gdPutChar(out, '\n');

    gdPutChar(out, 's');
    gdPutChar(out, 't');
    gdPutChar(out, 'a');
    gdPutChar(out, 't');
    gdPutChar(out, 'i');
    gdPutChar(out, 'c');
    gdPutChar(out, ' ');
    gdPutChar(out, 'u');
    gdPutChar(out, 'n');
    gdPutChar(out, 's');
    gdPutChar(out, 'i');
    gdPutChar(out, 'g');
    gdPutChar(out, 'n');
    gdPutChar(out, 'e');
    gdPutChar(out, 'd');
    gdPutChar(out, ' ');
    gdPutChar(out, 'c');
    gdPutChar(out, 'h');
    gdPutChar(out, 'a');
    gdPutChar(out, 'r');
    gdPutChar(out, ' ');
    for (i = 0; base[i]; i++) {
        gdPutChar(out, base[i]);
    }
    gdPutChar(out, '_');
    gdPutChar(out, 'd');
    gdPutChar(out, 'a');
    gdPutChar(out, 't');
    gdPutChar(out, 'a');
    gdPutChar(out, '[');
    for (i = 0; width; i++) {
        int d = width % 10;
        width = width / 10;
        gdPutChar(out, '0' + d);
    }
    for (i = i - 1; i >= 0; i--) {
        gdPutChar(out, '0');
    }
    gdPutChar(out, ']');
    gdPutChar(out, ' ');
    gdPutChar(out, '=');
    gdPutChar(out, ' ');
    gdPutChar(out, '{');
    gdPutChar(out, '\n');

    for (i = 0; i < image->sy; i += 8) {
        for (j = 0; j < image->sx; j++) {
            unsigned char byte = 0;
            for (c = 0; c < 8 && i + c < image->sy; c++) {
                if (gdImageGetPixel(image, j, i + c) == fg) {
                    byte |= (1 << (7 - c));
                }
            }
            gdPutChar(out, '0');
            gdPutChar(out, 'x');
            gdPutChar(out, ((byte >> 4) < 10) ? ('0' + (byte >> 4)) : ('a' + (byte >> 4) - 10));
            gdPutChar(out, (byte & 0x0F) < 10 ? ('0' + (byte & 0x0F)) : ('a' + (byte & 0x0F) - 10));
            if (j != image->sx - 1) {
                gdPutChar(out, ',');
                if ((j + 1) % 8 == 0) {
                    gdPutChar(out, ' ');
                } else {
                    gdPutChar(out, ' ');
                }
                if (j % 32 == 31) {
                    gdPutChar(out, '\n');
                }
            } else if (i + 7 < image->sy) {
                gdPutChar(out, ',');
                gdPutChar(out, '\n');
            }
        }
    }

    gdPutChar(out, '};');
}
